function set_at(xs: list[option[int]], i: int, v: option[int]) -> (result: list[option[int]]) {
    require ((0 <= i) ∧
    (i < len(xs)));
    ensure ((len(result) == len(xs)) ∧
    (∀(k: int) ::
        ((0 <= k < len(xs)) ==>
            (result[k] == (if (k == i) then v else xs[k])))));
}
